namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Spaghetti Carbonara", Category = "Pasta", Ingredients = "Spaghetti, Eggs, Pancetta, Parmesan, Black Pepper", Steps = "1. Cook pasta\n2. Fry pancetta\n3. Mix eggs and cheese\n4. Combine all with pasta water", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Margherita Pizza", Category = "Pizza", Ingredients = "Pizza Dough, Tomato Sauce, Mozzarella, Fresh Basil, Olive Oil", Steps = "1. Roll out dough\n2. Spread sauce\n3. Add mozzarella\n4. Bake at 250°C for 10 min\n5. Top with basil", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Curries", Ingredients = "Chicken, Yogurt, Tomato Puree, Cream, Garam Masala, Cumin, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill chicken\n3. Make sauce with tomato, cream, and spices\n4. Combine and simmer", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark Chocolate, Butter, Eggs, Sugar, Flour", Steps = "1. Melt chocolate and butter\n2. Whisk eggs and sugar\n3. Fold in flour\n4. Pour into ramekins\n5. Bake at 200°C for 12 min", AverageRating = 4.9, RatingCount = 30 },
        new Recipe { Id = 5, Title = "Caesar Salad", Category = "Salads", Ingredients = "Romaine Lettuce, Croutons, Parmesan, Caesar Dressing, Lemon", Steps = "1. Wash and chop lettuce\n2. Make dressing\n3. Toss lettuce with dressing\n4. Top with croutons and parmesan", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 6, Title = "Penne Arrabbiata", Category = "Pasta", Ingredients = "Penne, Tomatoes, Garlic, Chili Flakes, Olive Oil, Parsley", Steps = "1. Cook penne\n2. Sauté garlic and chili in oil\n3. Add tomatoes and simmer\n4. Toss with pasta", AverageRating = 4.3, RatingCount = 10 },
        new Recipe { Id = 7, Title = "Tiramisu", Category = "Desserts", Ingredients = "Mascarpone, Espresso, Ladyfingers, Eggs, Sugar, Cocoa Powder", Steps = "1. Mix egg yolks with sugar\n2. Fold in mascarpone\n3. Dip ladyfingers in espresso\n4. Layer mascarpone and ladyfingers\n5. Dust with cocoa", AverageRating = 4.7, RatingCount = 18 },
    };

    private readonly Lock _lock = new();

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is null) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _recipes.Max(r => r.Id) + 1;
            _recipes.Add(recipe);
        }
    }
}

